import {Stack, Dialog, Pagination} from '@primer/react'
import {DataTable, Table, type Column} from '@primer/react/experimental'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState, useEffect, useMemo} from 'react'
import styles from './LicenseHistoryDetail.module.css'
import {formatDate} from '../services/license-history-helpers'
import type {LicenseChange, DetailedChange} from '../types/license-change'
import {CHANGE_TYPE_LABELS} from '../types/license-change'

interface LicenseHistoryDetailProps {
  licenseChange: LicenseChange
  isOpen: boolean
  onClose: () => void
}

const ITEMS_PER_PAGE = 10

export function LicenseHistoryDetail({licenseChange, isOpen, onClose}: LicenseHistoryDetailProps) {
  const [currentPage, setCurrentPage] = useState(1)

  // Reset to first page when dialog opens with new license change
  useEffect(() => {
    if (isOpen && licenseChange) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setCurrentPage(1)
    }
  }, [isOpen, licenseChange])

  // Apply client-side pagination to the detailed events
  const {currentPageEvents, totalPages, totalCount} = useMemo(() => {
    const detailedEvents = licenseChange?.detailedEvents || []
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE
    const endIndex = startIndex + ITEMS_PER_PAGE
    const pageData = detailedEvents.slice(startIndex, endIndex)
    const calculatedTotalPages = Math.max(1, Math.ceil(detailedEvents.length / ITEMS_PER_PAGE))
    return {
      currentPageEvents: pageData,
      totalPages: calculatedTotalPages,
      totalCount: detailedEvents.length,
    }
  }, [licenseChange?.detailedEvents, currentPage])

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  const columns: Array<Column<DetailedChange>> = [
    {
      header: 'User',
      field: 'user',
      renderCell: (row: DetailedChange) => {
        return (
          <Stack direction="horizontal" gap="condensed" className="f5 fgColor-default">
            <GitHubAvatar src={row.user.avatarUrl} alt="" size={20} />
            <span className={styles.username}>{row.user.login}</span>
          </Stack>
        )
      },
    },
    {
      header: 'Performed by',
      field: 'performedBy',
      renderCell: (row: DetailedChange) => {
        // Handle case where performedBy is null/undefined
        const defaultAvatar = 'https://avatars.githubusercontent.com/u/0'
        const performedByAvatar =
          row.performedBy?.avatarUrl && row.performedBy.avatarUrl !== '' ? row.performedBy.avatarUrl : defaultAvatar
        const performedByLogin =
          row.performedBy?.login && row.performedBy.login !== '' ? row.performedBy.login : 'system'

        return (
          <Stack direction="horizontal" gap="condensed" className="f5 fgColor-default">
            <GitHubAvatar src={performedByAvatar} alt="" size={20} />
            <span className={styles.username}>{performedByLogin}</span>
          </Stack>
        )
      },
    },
    {
      header: 'Performed on',
      field: 'performedAt',
      renderCell: (row: DetailedChange) => {
        return <span className="f5 fgColor-default">{formatDate(row.performedAt)}</span>
      },
    },
  ]

  if (!isOpen || !licenseChange) return null

  const eventLabel = `${CHANGE_TYPE_LABELS[licenseChange.changeType]} ${licenseChange.licenseCount} ${
    licenseChange.licenseCount === 1 ? 'license' : 'licenses'
  }`

  // Only show the effective date since that's what groups the changes
  const dateLabel = `Effective on: ${formatDate(licenseChange.effectiveDate)}`

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE + 1
  const endIndex = (currentPage - 1) * ITEMS_PER_PAGE + currentPageEvents.length

  return (
    <Dialog onClose={onClose} title={eventLabel} subtitle={dateLabel}>
      <Dialog.Body>
        <Table.Container>
          <DataTable data={currentPageEvents} columns={columns} />
        </Table.Container>

        {totalPages > 1 && (
          <Stack direction="horizontal" justify="space-between" align="center">
            <span className={styles.paginationInfo}>
              {startIndex}–{endIndex} of {totalCount}
            </span>
            <Pagination
              showPages={false}
              currentPage={currentPage}
              pageCount={totalPages}
              onPageChange={(event, page) => {
                event.preventDefault()
                handlePageChange(page)
              }}
            />
          </Stack>
        )}
      </Dialog.Body>

      <Dialog.Footer>
        <Dialog.Buttons
          buttons={[
            {
              content: 'Close',
              onClick: onClose,
            },
          ]}
        />
      </Dialog.Footer>
    </Dialog>
  )
}
