import {useState, useEffect} from 'react'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {useMatchCandidateSearch} from '../hooks/use-match-candidate-search'
import {VisualStudioMatchPicker} from './VisualStudioMatchPicker'
import type {SubscriptionIdentifier} from '../types/subscription-identifier'

// Minimum length of input before search is triggered
const MIN_SEARCH_LENGTH = 1

export function VisualStudioMatchPickerContainer({
  caption,
  currentMatch,
  onChange,
  onUserInput,
  selectedSubscriptionIdentifier,
  showError = false,
}: {
  caption?: React.ReactNode
  currentMatch?: SubscriptionIdentifier
  onChange: (val: SubscriptionIdentifier | null) => void
  onUserInput?: () => void
  selectedSubscriptionIdentifier: SubscriptionIdentifier | null
  showError?: boolean
}) {
  const {slug} = useNavigation()
  const [inputValue, setInputValue] = useState(
    selectedSubscriptionIdentifier?.email ?? selectedSubscriptionIdentifier?.identity ?? '',
  )
  const [selectedMenuItemId, setSelectedMenuItemId] = useState<string | null>(null)
  const [subscriptionIdentifiers, setSubscriptionIdentifiers] = useState<SubscriptionIdentifier[]>([])

  const {search, loading, results: matchCandidates} = useMatchCandidateSearch(slug, currentMatch)

  // Effect to search for subscription identifiers when input value changes
  useEffect(() => {
    if (inputValue.length >= MIN_SEARCH_LENGTH) {
      search(inputValue)
    } else {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSubscriptionIdentifiers([]) // Clear results if input is too short
    }
  }, [inputValue, search])

  // Effect to update the subscription identifiers when candidate search results change
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSubscriptionIdentifiers(matchCandidates)
  }, [matchCandidates])

  // We split the subscription identifiers out into two menu items each:
  // one for the `email`, one for the `identity`, so the user can match against either.
  const menuItems = subscriptionIdentifiers
    .flatMap(item => {
      const items = []
      // Note, `id` is used as a unique identifier for the menu item
      if (item.email) {
        items.push({id: `${item.id}__email`, text: item.email})
      }
      if (item.identity && item.identity !== item.email) {
        items.push({id: `${item.id}__identity`, text: item.identity})
      }
      return items
    })
    .sort((a, b) => a.text.localeCompare(b.text)) // Sort alphabetically
    .slice(0, 10) // Limit to 10 items (server call fetches 10 SubscriptionIdentifiers, but since we can have 2 items per SubscriptionIdentifier after mapping, we want to re-limit to 10)

  return (
    <VisualStudioMatchPicker
      inputValue={inputValue}
      menuItems={menuItems}
      selected={selectedMenuItemId ? (menuItems.find(item => item.id === selectedMenuItemId) ?? null) : null}
      loading={inputValue.length >= MIN_SEARCH_LENGTH ? loading : false}
      showError={showError}
      caption={caption}
      onInputChange={val => {
        setInputValue(val)
        setSubscriptionIdentifiers([]) // Clear stale results immediately to prevent showing old options
        setSelectedMenuItemId(null) // Clear stale selection to prevent mismatch
        onUserInput?.()

        // Validate the input — but don't change the inputValue itself
        const normalizedVal = val.toLowerCase()
        const stillMatchesSelected =
          selectedSubscriptionIdentifier &&
          (selectedSubscriptionIdentifier.email?.toLowerCase() === normalizedVal ||
            selectedSubscriptionIdentifier.identity?.toLowerCase() === normalizedVal)

        if (!stillMatchesSelected) {
          onChange(null)
        }
      }}
      onItemSelect={item => {
        if (!item) {
          setSelectedMenuItemId(null)
          onChange(null)
          return
        }

        setSelectedMenuItemId(item.id)
        setInputValue(item.text)

        const subscriptionIdentifierId = item.id.split('__')[0] // Extract the ID part before the '__' (if present)
        const originalItem = subscriptionIdentifiers.find(i => String(i.id) === subscriptionIdentifierId)
        if (originalItem) {
          onChange(originalItem)
        }
      }}
    />
  )
}
