import {Stack, Pagination, Button} from '@primer/react'
import {SortDescIcon, PlusIcon, DashIcon, AlertIcon, BookIcon} from '@primer/octicons-react'
import {DataTable, Table, Blankslate, type Column} from '@primer/react/experimental'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {clsx} from 'clsx'
import {useState} from 'react'
import {LicenseHistoryDetail} from './LicenseHistoryDetail'
import styles from './LicenseHistory.module.css'
import {pluralize} from '@github-ui/licensing-common/helpers/pluralize'
import {formatDate} from '../services/license-history-helpers'
import type {LicenseChange, ChangeType} from '../types/license-change'
import {CHANGE_TYPE_LABELS, CHANGE_TYPE_COLORS} from '../types/license-change'

const CHANGE_TYPE_ICONS: Record<ChangeType, React.ReactElement> = {
  added: <PlusIcon size={16} />,
  removed: <DashIcon size={16} />,
} as const

interface LicenseHistoryProps {
  changes: LicenseChange[]
  isError: boolean
  isFetching: boolean
  currentPage: number
  totalPages: number
  onPageChange: (page: number) => void
}

export function LicenseHistory({
  changes,
  isError,
  isFetching,
  currentPage,
  totalPages,
  onPageChange,
}: LicenseHistoryProps) {
  const [selectedChange, setSelectedChange] = useState<LicenseChange | null>(null)

  const handleViewDetail = (change: LicenseChange) => {
    setSelectedChange(change)
  }

  const handleCloseDetail = () => {
    setSelectedChange(null)
  }

  if (isError) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <AlertIcon size="medium" className="fgColor-muted" />
        </Blankslate.Visual>
        <Blankslate.Heading>License history cannot be loaded</Blankslate.Heading>
        <Blankslate.Description>
          The license history is currently unavailable due to a system error. Try reloading the page, or if the problem
          persists,{' '}
          <a href="https://support.github.com/contact" style={{textDecoration: 'underline'}}>
            contact support
          </a>
          .
        </Blankslate.Description>
      </Blankslate>
    )
  }

  if (changes.length === 0 && !isFetching) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <BookIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>No license history found</Blankslate.Heading>
        <Blankslate.Description> No license history changes were found for this enterprise.</Blankslate.Description>
      </Blankslate>
    )
  }

  const columns: Array<Column<LicenseChange>> = [
    {
      header: 'Events',
      field: 'changeType',
      renderCell: (row: LicenseChange) => {
        const colorKey = CHANGE_TYPE_COLORS[row.changeType]
        const colorClass = styles[colorKey as keyof typeof styles]
        const icon = CHANGE_TYPE_ICONS[row.changeType]
        const label = CHANGE_TYPE_LABELS[row.changeType]

        return (
          <Stack direction="horizontal" gap="condensed" className={clsx('f5 fgColor-default', styles.eventCell)}>
            <div className={clsx(styles.icon, colorClass)}>{icon}</div>
            <span className={styles.eventLabel}>
              {label} {pluralize(row.licenseCount, 'license')}
            </span>
          </Stack>
        )
      },
    },
    {
      header: () => (
        <Stack direction="horizontal" gap="condensed" align="center">
          <span>Effective date</span>
          <SortDescIcon size={12} className={styles.sortIcon} />
        </Stack>
      ),
      field: 'effectiveDate',
      renderCell: row => {
        return <span className="f5 fgColor-default">{formatDate(row.effectiveDate)}</span>
      },
    },
    {
      header: 'Performed by',
      field: 'user',
      renderCell: row => {
        const mainUser = row.user
        const firstAdditionalUser = row.additionalUsers?.[0]
        const firstAdditionalUserLogin = firstAdditionalUser?.login ?? String(firstAdditionalUser)
        const firstAdditionalUserAvatar = firstAdditionalUser?.avatarUrl ?? 'https://avatars.githubusercontent.com/u/0'

        // Handle case where mainUser is null/undefined
        const defaultAvatar = 'https://avatars.githubusercontent.com/u/0'
        const userAvatar = mainUser?.avatarUrl && mainUser.avatarUrl !== '' ? mainUser.avatarUrl : defaultAvatar
        const userLogin = mainUser?.login && mainUser.login !== '' ? mainUser.login : 'system'

        return (
          <Stack direction="horizontal" gap="condensed" className="f5 fgColor-default">
            <div className={styles.avatarStack}>
              <GitHubAvatar src={userAvatar} alt="" size={20} />
              {row.additionalUsers && row.additionalUsers.length > 0 && (
                <GitHubAvatar src={firstAdditionalUserAvatar} alt="" size={20} className={styles.overlappingAvatar} />
              )}
            </div>
            <Stack direction="horizontal" gap="none">
              <span className={styles.username}>{userLogin}</span>
              {row.additionalUsers && row.additionalUsers.length > 0 && (
                <span className={styles.additionalUsers}>
                  {row.additionalUsers.length === 1
                    ? `, ${firstAdditionalUserLogin}`
                    : `, ${firstAdditionalUserLogin}, + ${row.additionalUsers.length - 1} more`}
                </span>
              )}
            </Stack>
          </Stack>
        )
      },
    },
    {
      id: 'actions',
      header: () => <span className="sr-only">Actions</span>,
      maxWidth: '120px',
      renderCell: (row: LicenseChange) => {
        return (
          <Button size="small" alignContent="center" variant="invisible" onClick={() => handleViewDetail(row)}>
            View detail
          </Button>
        )
      },
    },
  ]

  return (
    <>
      <div className={styles.container}>
        <Table.Container>
          {isFetching ? (
            <Table.Skeleton columns={columns} rows={changes.length || 3} />
          ) : (
            <DataTable data={changes} columns={columns} />
          )}
        </Table.Container>

        {!isFetching && totalPages > 1 && (
          <Pagination
            currentPage={currentPage}
            pageCount={totalPages}
            onPageChange={(event, page) => {
              event.preventDefault()
              onPageChange(page)
            }}
          />
        )}
      </div>

      {selectedChange && (
        <LicenseHistoryDetail licenseChange={selectedChange} isOpen={!!selectedChange} onClose={handleCloseDetail} />
      )}
    </>
  )
}
