import {Autocomplete, FormControl} from '@primer/react'
import styles from './VisualStudioMatchPicker.module.css'

export function VisualStudioMatchPicker({
  inputValue,
  menuItems,
  selected,
  loading,
  showError = false,
  caption,
  onInputChange,
  onItemSelect,
}: {
  inputValue: string
  menuItems: Array<{id: string; text: string}>
  selected: {id: string; text: string} | null
  loading: boolean
  showError?: boolean
  caption?: React.ReactNode
  onInputChange: (val: string) => void
  onItemSelect: (item: {id: string; text: string} | null) => void
}) {
  const hasValidationError = showError && !selected

  return (
    <FormControl>
      <FormControl.Label id="vs-login-email" required>
        Visual Studio login email
      </FormControl.Label>
      <Autocomplete>
        <Autocomplete.Input
          block
          value={inputValue}
          onChange={e => {
            onInputChange(e.target.value)
          }}
          placeholder="Search by email or UPN"
          autoComplete="off"
          aria-invalid={hasValidationError}
          validationStatus={hasValidationError ? 'error' : undefined}
        />
        {(loading || menuItems.length > 0) && (
          <Autocomplete.Overlay width="large">
            {menuItems.length >= 10 && !loading && (
              <div className="tmp-pt-3 tmp-mx-3 f6 text-semibold fgColor-muted">
                Showing top 10 results. Type more to filter.
              </div>
            )}
            <div className={styles.hideLeadingAction}>
              <Autocomplete.Menu
                aria-labelledby="vs-login-email"
                items={menuItems}
                loading={loading}
                selectedItemIds={selected ? [selected.id] : []}
                filterFn={() => true} // Server-side filtering; disable built-in client-side filtering
                emptyStateText="No results found. Try adjusting your search."
                onSelectedChange={items => {
                  const picked = Array.isArray(items) ? items[0] : undefined
                  const selectedItem = picked ? menuItems.find(item => item.id === picked.id) : null
                  onItemSelect(selectedItem ?? null)
                }}
              />
            </div>
          </Autocomplete.Overlay>
        )}
      </Autocomplete>
      {showError && !selected && (
        <FormControl.Validation variant="error">
          Please enter a valid email address or UPN (User Principal Name).
        </FormControl.Validation>
      )}
      {caption != null && <FormControl.Caption>{caption}</FormControl.Caption>}
    </FormControl>
  )
}
